suppressPackageStartupMessages({library(Seurat);library(ggplot2);library(dplyr);library(tidyr);library(readr);library(ggrastr);library(patchwork)})
text_size_pt<-7;width_mm<-180;height_mm<-235;point_size<-.18;line_width<-.25;continuous_map<-"viridis"
wong<-c("#E69F00","#56B4E9","#009E73","#CC79A7","#D55E00","#F0E442","#0072B2","#000000")
subtypes<-c("ECM_CAF","TGFb_CAF","iCAF","Vascular_CAF","Hypoxia_CAF","apCAF")
root<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project";indir<-file.path(root,"final_analysis_20260907/Figure1_CAF_atlas");outdir<-file.path(root,"final_analysis_20260907/Figure2_CAF_programs");dir.create(outdir,recursive=TRUE,showWarnings=FALSE)
pub<-theme_classic(base_size=text_size_pt,base_family="Times New Roman")+theme(plot.title=element_blank(),plot.subtitle=element_blank(),axis.title=element_text(size=text_size_pt),axis.text=element_text(size=text_size_pt),legend.title=element_text(size=text_size_pt),legend.text=element_text(size=text_size_pt),strip.text=element_text(size=text_size_pt),axis.ticks=element_line(linewidth=line_width),panel.grid.major=element_line(colour="grey90",linewidth=line_width),panel.grid.minor=element_blank(),plot.margin=margin(2,2,2,2,"mm"))
marker<-read_csv(file.path(indir,"Figure1C_marker_dotplot_source.csv"),show_col_types=FALSE)%>%mutate(CAF_subtype_global=factor(CAF_subtype_global,levels=subtypes))
mean_score<-read_csv(file.path(indir,"Figure1D_program_scores_source.csv"),show_col_types=FALSE)%>%mutate(CAF_subtype_global=factor(CAF_subtype_global,levels=subtypes))
composition<-read_csv(file.path(indir,"Figure1E_cohort_subtype_composition_source.csv"),show_col_types=FALSE)%>%mutate(CAF_subtype_global=factor(CAF_subtype_global,levels=subtypes))
cor_df<-read_csv(file.path(indir,"Figure1F_global_program_correlation_source.csv"),show_col_types=FALSE)%>%mutate(program_x=factor(sub("CAF_score_global_","",program_x),levels=subtypes),program_y=factor(sub("CAF_score_global_","",program_y),levels=rev(subtypes)))
cell<-read_csv(file.path(indir,"global_annotation_cell_scores.csv"),show_col_types=FALSE);cell$global_subtype<-factor(cell$global_subtype,levels=subtypes)
long<-cell%>%select(cell_id,global_subtype,all_of(subtypes))%>%pivot_longer(all_of(subtypes),names_to="program",values_to="score")
pA<-ggplot(marker,aes(gene,CAF_subtype_global))+geom_point(aes(size=pct_detected,colour=mean_expression))+scale_colour_viridis_c(option=continuous_map)+scale_size(range=c(.4,4),name="% detected")+labs(x=NULL,y=NULL,colour="Mean expression")+pub+theme(axis.text.x=element_text(angle=45,hjust=1),panel.grid=element_blank())
pB<-ggplot(mean_score,aes(program,CAF_subtype_global,fill=score))+geom_tile(colour="white",linewidth=line_width)+scale_fill_viridis_c(option=continuous_map,name="Mean score")+labs(x=NULL,y=NULL)+pub+theme(panel.grid=element_blank())
pC<-ggplot(long,aes(global_subtype,score,fill=global_subtype))+geom_violin(scale="width",trim=TRUE,colour="grey25",linewidth=line_width,alpha=.75)+geom_boxplot(width=.12,outlier.size=.15,linewidth=line_width)+facet_wrap(~program,nrow=2,scales="free_y")+scale_fill_manual(values=setNames(wong[seq_along(subtypes)],subtypes),guide="none")+labs(x=NULL,y="Cell-level module score")+pub+theme(axis.text.x=element_text(angle=45,hjust=1))
obj<-readRDS(file.path(indir,"GSE135337_GSE190888_GSE130001_GSE129845_CAF_global_annotated.rds"))
ud<-Embeddings(obj,reduction="umap");keep<-intersect(rownames(ud),cell$cell_id)
umap<-as.data.frame(ud[keep,1:2,drop=FALSE])%>%tibble::rownames_to_column("cell_id")%>%left_join(cell,by="cell_id")%>%pivot_longer(all_of(subtypes),names_to="program",values_to="score")
pD<-ggplot(umap,aes(UMAP_1,UMAP_2,colour=score))+ggrastr::geom_point_rast(size=point_size,alpha=.65,raster.dpi=500)+facet_wrap(~program,nrow=2)+scale_colour_viridis_c(option=continuous_map,name="Score")+coord_equal()+labs(x="UMAP 1",y="UMAP 2")+pub
pE<-ggplot(composition,aes(dataset,fraction,fill=CAF_subtype_global))+geom_col(width=.72,colour="white",linewidth=line_width)+scale_fill_manual(values=setNames(wong[seq_along(subtypes)],subtypes),drop=FALSE)+scale_y_continuous(labels=scales::percent_format(accuracy=1),expand=expansion(mult=c(0,.04)))+labs(x=NULL,y="CAF composition",fill="CAF subtype")+pub+theme(axis.text.x=element_text(angle=45,hjust=1))
pF<-ggplot(cor_df,aes(program_x,program_y,fill=rho))+geom_tile(colour="white",linewidth=line_width)+geom_text(aes(label=sprintf("%.2f",rho)),size=text_size_pt/3.2,family="Times New Roman")+scale_fill_viridis_c(option=continuous_map,limits=c(-1,1),name="Spearman\nρ")+labs(x=NULL,y=NULL)+pub+theme(axis.text.x=element_text(angle=45,hjust=1),panel.grid=element_blank())
fig<-(pA|pB)/(pC|pD)/(pE|pF)+plot_annotation(tag_levels="A")&theme(plot.tag=element_text(size=text_size_pt,family="Times New Roman"))
ggsave(file.path(outdir,"Figure2_CAF_programs.pdf"),fig,width=width_mm,height=height_mm,units="mm",device=cairo_pdf,bg="white");ggsave(file.path(outdir,"Figure2_CAF_programs.png"),fig,width=width_mm,height=height_mm,units="mm",dpi=300,bg="white")
write_csv(marker,file.path(outdir,"Figure2A_marker_dotplot_source.csv"));write_csv(mean_score,file.path(outdir,"Figure2B_program_score_heatmap_source.csv"));write_csv(long,file.path(outdir,"Figure2C_cell_program_score_source.csv"));write_csv(umap,file.path(outdir,"Figure2D_program_score_umap_source.csv"));write_csv(composition,file.path(outdir,"Figure2E_cohort_composition_source.csv"));write_csv(cor_df,file.path(outdir,"Figure2F_program_correlation_source.csv"))
writeLines(c("Figure 2 CAF functional programs","No new biological analysis; reused existing marker, score, composition and correlation results."),file.path(outdir,"Figure2_STATUS.txt"))
